/* Intersection entre les compétitions configurées et celles réellement
 * actives chez The Odds API. GET /v4/sports est GRATUIT : cette
 * vérification ne coûte rien et supprime toute clé périmée du chemin
 * d'exécution. On n'invente jamais une clé. */

const cfg = $('Config').first().json;

const actives = new Set(
  $input.all()
    .map(i => i.json)
    .filter(s => s && s.key && s.active !== false)
    .map(s => s.key)
);

const retenues = [];
const ecartees = [];
for (const c of cfg.competitions) {
  (actives.has(c.key) ? retenues : ecartees).push(c);
}

if (ecartees.length) {
  console.warn(
    'Clés absentes ou inactives dans /v4/sports, écartées de ce cycle : ' +
    ecartees.map(c => c.key).join(', ')
  );
}
if (!retenues.length) {
  throw new Error(
    'Aucune compétition configurée n\'est active chez The Odds API. ' +
    'Vérifier la liste `competitions` du nœud Config contre GET /v4/sports.'
  );
}

return retenues.map(c => ({ json: c }));

/* Normalisation + déduplication des affiches.
 * Rapprochement flou de noms (coefficient de Dice sur bigrammes de
 * caractères) BORNÉ par la date de coup d'envoi (± 6 h), comme spécifié
 * pour l'agent 1. Sans la borne temporelle, deux confrontations de la même
 * paire à des dates différentes fusionneraient à tort. */

const cfg   = $('Config').first().json;
const byKey = new Map(cfg.competitions.map(c => [c.key, c]));

const strip = (s) => String(s ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')   // retire les diacritiques
  .toLowerCase()
  .replace(/\b(fc|cf|afc|sc|ac|as|ss|ssc|cd|ud|rc|sv|vfl|vfb|tsg|fk|bk|if|club|calcio)\b/g, ' ')
  .replace(/[^a-z0-9 ]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const bigrams = (s) => {
  const t = ' ' + s + ' ';
  const out = new Set();
  for (let i = 0; i < t.length - 1; i++) out.add(t.slice(i, i + 2));
  return out;
};

const dice = (a, b) => {
  const A = bigrams(a), B = bigrams(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const g of A) if (B.has(g)) inter++;
  return (2 * inter) / (A.size + B.size);
};

const SEUIL = 0.82;
const FENETRE_MS = 6 * 3600 * 1000;

const brut = $input.all()
  .map(i => i.json)
  .filter(e => e && e.id && e.home_team && e.away_team && e.commence_time);

const gardes = [];
for (const e of brut) {
  const comp = byKey.get(e.sport_key);
  if (!comp) continue;                       // compétition non configurée : ignorée

  const t = Date.parse(e.commence_time);
  if (!Number.isFinite(t)) continue;

  const h = strip(e.home_team);
  const a = strip(e.away_team);
  if (!h || !a) continue;

  const doublon = gardes.find(k =>
    Math.abs(k._t - t) <= FENETRE_MS && (
      (dice(k._h, h) >= SEUIL && dice(k._a, a) >= SEUIL) ||
      (dice(k._h, a) >= SEUIL && dice(k._a, h) >= SEUIL)   // inversion domicile/extérieur
    )
  );
  if (doublon) {
    if (!doublon.sources.includes(e.sport_key)) doublon.sources.push(e.sport_key);
    continue;
  }

  gardes.push({
    _h: h, _a: a, _t: t,
    event_id         : e.id,
    sport            : comp.sport,
    competition_key  : comp.key,
    competition_label: comp.label,
    importance       : comp.importance,
    home             : e.home_team,
    away             : e.away_team,
    starts_at        : e.commence_time,
    fixture_key      : comp.key + '|' + h + '|' + a + '|' + new Date(t).toISOString().slice(0, 10),
    sources          : [e.sport_key]
  });
}

console.log('Affiches brutes : ' + brut.length + ' — après déduplication : ' + gardes.length);
return gardes.map(g => ({ json: g }));

/* AGENT 2 — Priorisation. Le cœur de la conception.
 *
 * Le quota commande, pas le calendrier. Ce nœud ne sélectionne JAMAIS plus
 * de matchs que le budget du cycle ne permet d'en payer en cotes.
 *
 * priorité = poids_fenêtre × importance_compétition × ancienneté
 * (multiplicatif, conformément au livrable B)
 *
 * Si le quota est illisible, le cycle est REPORTÉ. Aucun crédit n'est
 * engagé à l'aveugle : une estimation fausse coûterait des crédits réels. */

const cfg = $('Config').first().json;

let q = {};
try { q = $('Quota PronoStat').first().json ?? {}; } catch (e) { q = {}; }

const restant = Number(q.odds_credits_remaining);
if (!Number.isFinite(restant)) {
  return [{ json: {
    skip   : true,
    reason : 'quota_indisponible',
    detail : 'GET /quota n\'a pas renvoyé odds_credits_remaining. Cycle reporté.'
  }}];
}

const utilisable = Math.max(0, restant - cfg.reserveCredits);

let budget, mode = cfg.allocationMode ?? 'share';
const reset = Date.parse(q.period_resets_at ?? '');

if (mode === 'pace' && Number.isFinite(reset) && reset > Date.now()) {
  /* Débit régulier jusqu'à la remise à zéro du quota. L'allocation par
   * cycle est presque toujours fractionnaire : on l'accumule dans les
   * données statiques plutôt que de l'arrondir à zéro à chaque passage. */
  const heuresRestantes = (reset - Date.now()) / 3600000;
  const st = $getWorkflowStaticData('global');
  const parCycle = utilisable * (cfg.cycleHours / Math.max(cfg.cycleHours, heuresRestantes));
  st.paceAccu = (Number(st.paceAccu) || 0) + parCycle;
  budget = Math.floor(st.paceAccu);
  st.paceAccu -= budget;
} else {
  if (mode === 'pace') {
    mode = 'share (repli)';   // period_resets_at absent : on ne devine pas la date
    console.warn('Mode pace demandé mais period_resets_at absent ou passé — repli sur share.');
  }
  budget = Math.floor(utilisable * cfg.maxQuotaSharePerCycle);
}

const creneaux = Math.floor(budget / cfg.creditsPerMatch);

if (creneaux < 1) {
  return [{ json: {
    skip    : true,
    reason  : 'budget_insuffisant',
    restant : restant,
    reserve : cfg.reserveCredits,
    detail  : 'Quota trop bas pour financer une seule affiche ce cycle.'
  }}];
}

/* Journal des analyses passées, fourni par GET /quota */
const journal = Array.isArray(q.recent_analyses) ? q.recent_analyses : [];
const couvert = new Set();
const vuLe    = new Map();
for (const a of journal) {
  if (!a || !a.fixture_key) continue;
  if (a.window) couvert.add(a.fixture_key + '@' + a.window);
  const t = Date.parse(a.analysed_at);
  if (Number.isFinite(t)) vuLe.set(a.fixture_key, Math.max(vuLe.get(a.fixture_key) ?? 0, t));
}

const now = Date.now();
const fenetrePour = (h) => cfg.windows.find(w => h <= w.maxHours) ?? null;

const notes = [];
let horsFenetre = 0, dejaCouvert = 0, tropFrais = 0;

for (const it of $input.all()) {
  const m = it.json;
  if (!m || !m.starts_at) continue;

  const h = (Date.parse(m.starts_at) - now) / 3600000;
  if (!(h > 0)) { horsFenetre++; continue; }          // déjà commencé

  const w = fenetrePour(h);
  if (!w) { horsFenetre++; continue; }                // au-delà de J-7

  if (couvert.has(m.fixture_key + '@' + w.name)) { dejaCouvert++; continue; }

  const dernier = vuLe.get(m.fixture_key);
  const ageH    = dernier ? (now - dernier) / 3600000 : Infinity;
  if (ageH < cfg.freshnessHours) { tropFrais++; continue; }

  const anciennete = dernier ? Math.min(1, ageH / 72) : 1;
  const score = w.weight
              * (0.35 + 0.65 * Number(m.importance ?? 0.5))
              * (0.50 + 0.50 * anciennete);

  notes.push({
    ...m,
    window           : w.name,
    hours_to_kickoff : Math.round(h * 10) / 10,
    priority         : Math.round(score * 1000) / 1000
  });
}

notes.sort((a, b) => (b.priority - a.priority) || (a.hours_to_kickoff - b.hours_to_kickoff));
const choisis = notes.slice(0, creneaux);

console.log(
  'Quota ' + restant + ' | mode ' + mode + ' | budget cycle ' + budget + ' crédits | ' + creneaux + ' créneaux | ' +
  'candidats ' + notes.length + ' | retenus ' + choisis.length +
  ' (hors fenêtre ' + horsFenetre + ', fenêtre déjà couverte ' + dejaCouvert + ', trop frais ' + tropFrais + ')'
);

if (!choisis.length) {
  return [{ json: { skip: true, reason: 'rien_a_analyser', candidats: notes.length } }];
}

return choisis.map((m, i) => ({ json: {
  ...m,
  _cycle: { mode, budget_credits: budget, creneaux, rang: i + 1, quota_restant: restant }
}}));

/* Le cycle n'engage rien. Ce n'est pas une erreur : c'est le comportement
 * attendu quand le quota est bas ou que rien n'a changé depuis le dernier
 * passage. Tracé pour l'audit. */
const j = $input.first().json;
console.log('Cycle sans action — motif : ' + (j.reason ?? 'inconnu'));
return [{ json: { cycle_skipped: true, at: new Date().toISOString(), ...j } }];

/* Sortie « done » de la boucle : bilan du cycle. */
const st = $getWorkflowStaticData('global');
const lignes = $input.all().map(i => i.json);
const bilan = {
  cycle_termine_a       : new Date().toISOString(),
  matchs_traites        : lignes.length,
  publiables            : lignes.filter(r => r.publiable).length,
  bloques               : lignes.filter(r => !r.publiable).length,
  credits_cotes_restants: st.oddsCreditsRemaining ?? null,
  credits_maj_le        : st.oddsCreditsUpdatedAt ?? null
};
console.log(JSON.stringify(bilan));
return [{ json: bilan }];

/* Coupe-circuit intra-cycle.
 * Le budget a été calculé au démarrage ; une exécution longue peut le
 * périmer. On relit ici le compteur réel renvoyé par The Odds API à
 * l'itération précédente (en-tête x-requests-remaining, persisté dans les
 * données statiques du workflow). Si la réserve est menacée, on s'arrête —
 * AVANT de dépenser des requêtes Serper sur un match qu'on ne pourra pas
 * coter. */

const cfg = $('Config').first().json;
const st  = $getWorkflowStaticData('global');
const m   = $input.first().json;

const live = Number(st.oddsCreditsRemaining);
const connu = Number.isFinite(live);
const ok = !connu || live >= (cfg.reserveCredits + cfg.creditsPerMatch);

if (!ok) console.warn('Coupe-circuit : ' + live + ' crédits restants, réserve ' + cfg.reserveCredits + '. Match ' + m.fixture_key + ' reporté.');

return [{ json: { ...m, _guard: { ok, live_credits: connu ? live : null } } }];

/* Mode « sans recherche web » (étape 3 du plan G) : searchesPerMatch = 0.
 *
 * Le moteur tourne sur ses seules sources internes. Tous les champs de
 * recherche sont explicitement marqués non_trouve AVEC leur motif : c'est le
 * repli prévu au livrable E, pas une donnée manquante silencieuse. La
 * confiance sera abaissée côté PronoStat, ce qui est le comportement voulu. */

const CHAMPS = ['form_home', 'form_away', 'injuries_home', 'injuries_away',
                'lineups', 'h2h', 'standings', 'context'];
const m = $input.first().json;
const research = {};
for (const c of CHAMPS) {
  research[c] = { status: 'non_trouve', reason: 'recherche web désactivée (searchesPerMatch = 0)' };
}
console.log('Sans recherche web — ' + m.fixture_key);
return [{ json: { ...m, research, _llm: { ok: false, mode: 'sans_recherche' } } }];

/* Point de convergence des deux branches (avec / sans recherche web).
 * Existe pour que les nœuds en aval disposent d'UNE référence stable,
 * quel que soit le chemin emprunté. Ne transforme rien. */
return $input.all().map(i => ({ json: i.json }));

/* AGENT 3 (2/3) — agrégation des résultats bruts + construction du prompt.
 *
 * Le nœud HTTP remplace le JSON de l'item : `_match` et `q` sont perdus.
 * On les récupère par index depuis le nœud amont — l'ordre est préservé,
 * un item de requête produit un item de réponse.
 *
 * Le prompt est construit ICI, pas dans le corps du nœud HTTP : cela évite
 * un échappement illisible et rend le prompt relisible dans l'exécution. */

const reqs = $('Requêtes de recherche').all().map(i => i.json);
const res  = $input.all().map(i => i.json);
const m    = reqs[0]._match;

if (reqs.length !== res.length) {
  console.warn('Appariement requête/réponse imparfait : ' + reqs.length +
               ' requêtes pour ' + res.length + ' réponses. Appariement par index, au mieux.');
}

const hote = (u) => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch (e) { return String(u); } };

let echecs = 0;
const dossier = res.map((r, i) => {
  const q = reqs[i]?.q ?? '(requête inconnue)';
  if (!r || r.error) { echecs++; return { requete: q, erreur: 'recherche indisponible', resultats: [] }; }
  const organic = Array.isArray(r.organic) ? r.organic.slice(0, 6) : [];
  return {
    requete   : q,
    answerBox : r.answerBox?.snippet ?? null,
    resultats : organic.map(o => ({
      source  : hote(o.link),
      titre   : o.title,
      extrait : o.snippet,
      date    : o.date ?? null,
      url     : o.link
    }))
  };
});

const systemPrompt = [
  'Tu es un EXTRACTEUR de données factuelles pour un moteur statistique.',
  'Tu ne prédis rien. Tu ne conseilles rien. Tu ne produis AUCUN pronostic,',
  'AUCUNE probabilité, AUCUNE cote. Le calcul se fait ailleurs.',
  '',
  'Tu ne renvoies QUE du JSON valide : pas de texte avant, pas de texte après,',
  'pas de bloc de code markdown.',
  '',
  'Chaque champ est un objet portant obligatoirement une clé "status".',
  'Les cinq statuts autorisés, et eux seuls :',
  '  "disponible"          — information trouvée, sourcée',
  '  "non_trouve"          — les recherches n\'ont rien donné',
  '  "non_publie"          — l\'information n\'existe pas encore (ex. compositions)',
  '  "source_inaccessible" — source identifiée mais contenu non lisible',
  '  "contradictoire"      — au moins deux sources s\'opposent',
  '',
  'RÈGLES ABSOLUES :',
  '1. N\'invente JAMAIS une valeur. Au moindre doute : "non_trouve".',
  '2. N\'harmonise JAMAIS deux sources qui se contredisent. Statut',
  '   "contradictoire" et clé "conflict" listant chaque version avec sa source.',
  '3. Toute valeur "disponible" porte une clé "sources" (noms de domaine)',
  '   non vide et une clé "collected_at" (ISO 8601).',
  '4. Ne déduis pas une statistique d\'une autre. Aucun calcul.',
  '5. Une absence de résultat n\'est pas un échec : c\'est une information.'
].join('\n');

const schema = {
  form_home     : '{status, value:{last5:["W","D","L",...], goals_for, goals_against}, sources[], collected_at}',
  form_away     : 'idem form_home',
  injuries_home : '{status, value:[{player, issue, expected_return}], sources[], collected_at}',
  injuries_away : 'idem injuries_home',
  lineups       : '{status, value:{home:[], away:[]}, sources[], collected_at}',
  h2h           : '{status, value:[{date, home, away, score}], sources[], collected_at}',
  standings     : '{status, value:{home_rank, away_rank, home_points, away_points}, sources[], collected_at}',
  context       : '{status, value:{stakes, travel, rest_days, weather, notes}, sources[], collected_at}'
};

const userPrompt = [
  'MATCH : ' + m.home + ' vs ' + m.away,
  'Compétition : ' + m.competition_label + ' (' + m.sport + ')',
  'Coup d\'envoi : ' + m.starts_at,
  'Fenêtre d\'analyse : ' + m.window,
  '',
  'RÉSULTATS DE RECHERCHE (' + dossier.length + ' requêtes, ' + echecs + ' en échec) :',
  JSON.stringify(dossier, null, 1),
  '',
  'Renvoie un objet JSON avec EXACTEMENT ces clés :',
  JSON.stringify(schema, null, 1),
  '',
  'Rappel : le statut est obligatoire sur chaque clé. Aucune valeur inventée.'
].join('\n');

return [{ json: {
  ...m,
  systemPrompt,
  userPrompt,
  _search: { requetes: dossier.length, echecs }
}}];

/* AGENT 3 (3/3) — validation de l'extraction.
 *
 * Un LLM peut renvoyer du texte hors JSON, un statut inventé, ou rien.
 * Aucune de ces trois défaillances ne doit polluer le moteur : tout champ
 * qui ne respecte pas le contrat est REMPLACÉ par "non_trouve" avec le
 * motif. On ne devine pas, on n'ignore pas silencieusement. */

const AUTORISES = new Set([
  'disponible', 'non_trouve', 'non_publie', 'source_inaccessible', 'contradictoire'
]);
const CHAMPS = [
  'form_home', 'form_away', 'injuries_home', 'injuries_away',
  'lineups', 'h2h', 'standings', 'context'
];

const brut = $input.first().json ?? {};

// Les prompts ne doivent PAS suivre dans la chaîne : ils gonfleraient
// inutilement le document Firestore (plafond 1 Mio) sans rien apporter.
const { systemPrompt, userPrompt, ...m } = $('Agrégation & prompt').first().json;

let texte = '';
try { texte = brut?.content?.[0]?.text ?? ''; } catch (e) { texte = ''; }

let extrait = null, erreurParse = null;
if (texte) {
  const propre = String(texte).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  const d = propre.indexOf('{'), f = propre.lastIndexOf('}');
  try {
    extrait = JSON.parse(d >= 0 && f > d ? propre.slice(d, f + 1) : propre);
  } catch (err) { erreurParse = err.message; }
} else {
  erreurParse = brut?.error ? 'appel LLM en échec' : 'réponse vide';
}

const research = {};
let valides = 0;
for (const c of CHAMPS) {
  const v = extrait?.[c];
  if (v && typeof v === 'object' && AUTORISES.has(v.status)) {
    // Un "disponible" sans source n'est pas exploitable : on le déclasse.
    if (v.status === 'disponible' && !(Array.isArray(v.sources) && v.sources.length)) {
      research[c] = { status: 'non_trouve', reason: 'valeur sans source — rejetée' };
    } else {
      research[c] = v; valides++;
    }
  } else {
    research[c] = {
      status : 'non_trouve',
      reason : extrait ? 'champ absent ou statut hors contrat'
                       : ('extraction illisible : ' + (erreurParse ?? 'inconnu'))
    };
  }
}

console.log('Extraction ' + m.fixture_key + ' : ' + valides + '/' + CHAMPS.length + ' champs valides');

return [{ json: {
  ...m,
  research,
  _llm: { ok: !!extrait, champs_valides: valides, parse_error: erreurParse }
}}];

/* AGENT 4 — normalisation des cotes + comptabilité du quota.
 *
 * Le nœud amont renvoie la réponse COMPLÈTE (fullResponse) pour lire les
 * en-têtes : x-requests-remaining est la seule source fiable du quota réel.
 * On la persiste dans les données statiques du workflow — c'est elle qui
 * alimente le coupe-circuit du cycle suivant.
 *
 * Le consensus robuste (médiane + tolérance 6 %) N'EST PAS calculé ici :
 * il est déjà implémenté et testé côté PronoStat. n8n transmet le brut. */

const st = $getWorkflowStaticData('global');
const r  = $input.first().json ?? {};
const m  = $('Dossier de recherche').first().json;

const headers = r.headers ?? {};
const restant = Number(headers['x-requests-remaining']);
const cout    = Number(headers['x-requests-last']);
if (Number.isFinite(restant)) {
  st.oddsCreditsRemaining = restant;
  st.oddsCreditsUpdatedAt = new Date().toISOString();
}

const corps = Array.isArray(r.body) ? r.body : (Array.isArray(r) ? r : []);
const ev = corps[0] ?? null;
const bks = ev?.bookmakers ?? [];

const market = ev ? {
  status          : bks.length ? 'disponible' : 'non_trouve',
  collected_at    : new Date().toISOString(),
  event_id        : ev.id,
  bookmaker_count : bks.length,
  regions         : $('Config').first().json.oddsRegions,
  bookmakers      : bks.map(b => ({
    name        : b.title,
    key         : b.key,
    last_update : b.last_update,
    markets     : Object.fromEntries(
      (b.markets ?? []).map(mk => [
        mk.key,
        (mk.outcomes ?? []).map(o => ({
          name  : o.name,
          price : o.price,
          point : (o.point === undefined ? null : o.point)
        }))
      ])
    )
  }))
} : {
  status       : 'non_trouve',
  collected_at : new Date().toISOString(),
  reason       : 'aucune cote renvoyée pour cet event_id',
  bookmakers   : []
};

console.log(
  'Cotes ' + m.fixture_key + ' : ' + (market.bookmaker_count ?? 0) + ' bookmakers | ' +
  'coût ' + (Number.isFinite(cout) ? cout : '?') + ' crédits | ' +
  'restant ' + (Number.isFinite(restant) ? restant : '?')
);

return [{ json: { ...m, market, _odds: {
  credits_remaining : Number.isFinite(restant) ? restant : null,
  credits_last_call : Number.isFinite(cout) ? cout : null
}}}];

/* AGENT 5 — vérification des sources.
 *
 * Ce nœud NE TRANCHE JAMAIS une contradiction. Il qualifie, il compte, il
 * signale. Arbitrer ici reviendrait à produire une opinion — précisément ce
 * que l'architecture interdit. Le moteur baissera la confiance lui-même. */

const cfg = $('Config').first().json;
const m   = $input.first().json;

const SENSIBLES = ['injuries_home', 'injuries_away', 'lineups'];
const research  = { ...(m.research ?? {}) };
const contradictions = [];
const quality = {};

for (const [champ, v] of Object.entries(research)) {
  const sources = Array.isArray(v.sources) ? v.sources : [];
  const uniques = [...new Set(sources.map(s => String(s).toLowerCase().trim()).filter(Boolean))];

  const q = {
    status       : v.status,
    source_count : uniques.length,
    sources      : uniques,
    sensible     : SENSIBLES.includes(champ),
    corrobore    : uniques.length >= cfg.minSourcesForSensitiveField
  };

  if (v.status === 'contradictoire') {
    contradictions.push({ field: champ, versions: Array.isArray(v.conflict) ? v.conflict : [] });
    q.arbitre = false;   // transmis tel quel, volontairement
    q.note = 'contradiction transmise sans arbitrage — le moteur abaissera la confiance';
  }

  if (v.status === 'disponible' && q.sensible && !q.corrobore) {
    research[champ] = { ...v, corroboration: 'source_unique' };
    q.note = 'information sensible confirmée par une seule source';
  }

  // Fraîcheur : une info de plus de 72 h sur un champ sensible est suspecte.
  const t = Date.parse(v.collected_at ?? '');
  if (Number.isFinite(t)) {
    q.age_hours = Math.round((Date.now() - t) / 36000) / 100;
    if (q.sensible && q.age_hours > 72) q.note = (q.note ? q.note + ' ; ' : '') + 'donnée ancienne';
  }

  quality[champ] = q;
}

if (contradictions.length) {
  console.warn(m.fixture_key + ' : ' + contradictions.length + ' contradiction(s) — ' +
               contradictions.map(c => c.field).join(', '));
}

return [{ json: { ...m, research, _quality: quality, _contradictions: contradictions } }];

/* AGENT 6 — fusion et construction du payload du livrable D.
 *
 * Règle du §9 appliquée sans exception : une valeur sans `status` est
 * REJETÉE, pas corrigée. Un champ rejeté est tracé dans `_rejected` pour
 * qu'une régression de l'extracteur soit visible dans le journal. */

const AUTORISES = new Set([
  'disponible', 'non_trouve', 'non_publie', 'source_inaccessible', 'contradictoire'
]);

const m = $input.first().json;
const research = {};
const rejetes  = [];

for (const [k, v] of Object.entries(m.research ?? {})) {
  if (v && typeof v === 'object' && AUTORISES.has(v.status)) research[k] = v;
  else rejetes.push(k);
}

const payload = {
  schema_version: '1.0',
  event: {
    sport           : m.sport,
    competition_key : m.competition_key,
    home            : m.home,
    away            : m.away,
    starts_at       : m.starts_at,
    event_id        : m.event_id,
    fixture_key     : m.fixture_key
  },
  research,
  market        : m.market ?? { status: 'non_trouve', collected_at: new Date().toISOString(), bookmakers: [] },
  quality       : m._quality ?? {},
  contradictions: m._contradictions ?? [],
  versions: {
    research_version : '1.0',
    orchestrator     : 'n8n',
    window           : m.window,
    data_timestamp   : new Date().toISOString()
  }
};

if (rejetes.length) console.warn('Champs rejetés (contrat de statut non respecté) : ' + rejetes.join(', '));

return [{ json: { payload, _rejected: rejetes, _priority: m.priority, _cycle: m._cycle ?? null } }];

